// lib/data/gita_data.dart
class GitaSloka {
  final int chapter;
  final int verse;
  final String chapterTitle;
  final String chapterTeluguTitle;
  final String sanskrit;
  final String transliteration;
  final String teluguMeaning;
  final String englishMeaning;

  const GitaSloka({
    required this.chapter,
    required this.verse,
    required this.chapterTitle,
    required this.chapterTeluguTitle,
    required this.sanskrit,
    required this.transliteration,
    required this.teluguMeaning,
    required this.englishMeaning,
  });
}

class GitaChapter {
  final int number;
  final String title;
  final String teluguTitle;
  final int verseCount;
  final String summary;
  final String teluguSummary;
  const GitaChapter({required this.number, required this.title, required this.teluguTitle, required this.verseCount, required this.summary, required this.teluguSummary});
}

