const List<GitaSloka> gitaSlokas = [
  // CHAPTER 1
  GitaSloka(chapter:1,verse:1,chapterTitle:'Arjuna Vishada Yoga',chapterTeluguTitle:'అర్జున విషాద యోగము',sanskrit:'धृतराष्ट्र उवाच |\nधर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः |\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय ||',transliteration:'dhṛtarāṣṭra uvāca | dharma-kṣetre kuru-kṣetre samavetā yuyutsavaḥ | māmakāḥ pāṇḍavāścaiva kimakurvata sañjaya',teluguMeaning:'ధృతరాష్ట్రుడు అడిగాడు: ఓ సంజయా! ధర్మక్షేత్రమైన కురుక్షేత్రమున యుద్ధకాంక్షతో చేరిన నా పుత్రులు మరియు పాండు పుత్రులు ఏమి చేసిరి?',englishMeaning:'Dhritarashtra said: O Sanjaya, what did my sons and the sons of Pandu do when they assembled on the holy field of Kurukshetra, eager for battle?'),
  GitaSloka(chapter:1,verse:20,chapterTitle:'Arjuna Vishada Yoga',chapterTeluguTitle:'అర్జున విషాద యోగము',sanskrit:'अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान् कपिध्वजः |\nप्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः ||',transliteration:'atha vyavasthitān dṛṣṭvā dhārtarāṣṭrān kapidhvajaḥ | pravṛtte śastrasampāte dhanurudyamya pāṇḍavaḥ',teluguMeaning:'అప్పుడు కపి ధ్వజుడైన అర్జునుడు, యుద్ధం ప్రారంభమవుతుండగా నిలబడిన ధృతరాష్ట్ర పుత్రులను చూసి ధనుస్సు ఎత్తాడు.',englishMeaning:'At that time Arjuna, whose flag was marked with Hanuman, took up his bow and prepared to shoot his arrows.'),
  GitaSloka(chapter:1,verse:28,chapterTitle:'Arjuna Vishada Yoga',chapterTeluguTitle:'అర్జున విషాద యోగము',sanskrit:'दृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् |\nसीदन्ति मम गात्राणि मुखं च परिशुष्यति ||',transliteration:'dṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam | sīdanti mama gātrāṇi mukhaṃ ca pariśuṣyati',teluguMeaning:'ఓ కృష్ణా! యుద్ధం చేయాలని ఉవ్విళ్ళూరే స్వజనులను చూసి నా అవయవాలు నీరసపడుతున్నాయి, నోరు ఆరిపోతోంది.',englishMeaning:'O Krishna, seeing my own kinsmen arrayed here eager to fight, my limbs fail and my mouth is parched.'),
  GitaSloka(chapter:1,verse:32,chapterTitle:'Arjuna Vishada Yoga',chapterTeluguTitle:'అర్జున విషాద యోగము',sanskrit:'न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च |\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा ||',transliteration:'na kāṅkṣe vijayaṃ kṛṣṇa na ca rājyaṃ sukhāni ca | kiṃ no rājyena govinda kiṃ bhogairjīvitena vā',teluguMeaning:'ఓ కృష్ణా! నాకు విజయం అక్కర్లేదు, రాజ్యం అక్కర్లేదు, సుఖాలు అక్కర్లేదు. ఓ గోవిందా! రాజ్యంతో ఏమి ప్రయోజనం?',englishMeaning:'O Krishna, I do not desire victory, nor kingdom, nor pleasures. O Govinda, of what avail is a kingdom or enjoyment or even life itself?'),
  GitaSloka(chapter:1,verse:47,chapterTitle:'Arjuna Vishada Yoga',chapterTeluguTitle:'అర్జున విషాద యోగము',sanskrit:'एवमुक्त्वार्जुनः संख्ये रथोपस्थ उपाविशत् |\nविसृज्य सशरं चापं शोकसंविग्नमानसः ||',transliteration:'evamuktvārjunaḥ saṃkhye rathopastha upāviśat | visṛjya saśaraṃ cāpaṃ śokasaṃvignamānasaḥ',teluguMeaning:'ఇలా పలికిన అర్జునుడు శోకంతో చలించిన మనసుతో బాణాలు మరియు విల్లు వదిలిపెట్టి రథం మీద కూర్చుండిపోయాడు.',englishMeaning:'Having spoken thus on the battlefield, Arjuna cast aside his bow and arrows and sat down on the chariot, his mind overwhelmed with grief.'),

  // CHAPTER 2
  GitaSloka(chapter:2,verse:2,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'कुतस्त्वा कश्मलमिदं विषमे समुपस्थितम् |\nअनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन ||',transliteration:'kutastvā kaśmalamidaṃ viṣame samupasthitam | anāryajuṣṭamasvargyamakīrtikaramarjuna',teluguMeaning:'ఓ అర్జునా! ఈ కష్ట సమయంలో ఈ మోహం నీకు ఎక్కడ నుండి వచ్చింది? ఇది అనార్యులకు తగినది, స్వర్గాన్ని ఇవ్వదు, అపకీర్తి కలిగిస్తుంది.',englishMeaning:'O Arjuna, how has this delusion overcome you at this crucial hour? It is not befitting a man who knows what is valuable in life.'),
  GitaSloka(chapter:2,verse:3,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते |\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप ||',transliteration:'klaibyaṃ mā sma gamaḥ pārtha naitattvayyupapadyate | kṣudraṃ hṛdayadaurbalyaṃ tyaktvottiṣṭha parantapa',teluguMeaning:'ఓ పార్థా! పురుషత్వహీనతకు లోను కాకు, నీకు ఇది తగదు. హృదయ దుర్బలతను వదిలిపెట్టి లేచి నిలుచో, ఓ శత్రు తాపకా!',englishMeaning:'O Partha, do not yield to this degrading impotence. Give up such petty weakness of heart and arise, O chastiser of the enemy.'),
  GitaSloka(chapter:2,verse:11,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे |\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः ||',transliteration:'aśocyānanvaśocastvaṃ prajñāvādāṃśca bhāṣase | gatāsūnagatāsūṃśca nānuśocanti paṇḍitāḥ',teluguMeaning:'శోకింపదగని వారిని గురించి శోకిస్తున్నావు, అయినా జ్ఞాన మాటలు పలుకుతున్నావు. పండితులు చనిపోయిన వారికి గాని, బతికి ఉన్న వారికి గాని శోకించరు.',englishMeaning:'While speaking learned words, you are mourning for what is not worthy of grief. Those who are wise lament neither for the living nor for the dead.'),
  GitaSloka(chapter:2,verse:12,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः |\nन चैव न भविष्यामः सर्वे वयमतः परम् ||',transliteration:'na tvevāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ | na caiva na bhaviṣyāmaḥ sarve vayamataḥ param',teluguMeaning:'ఏ కాలంలోనూ నేను లేకపోలేదు, నువ్వు లేకపోలేదు, ఈ రాజులు లేకపోలేదు. ఇకముందు కూడా మనమందరం ఉంటాము.',englishMeaning:'Never was there a time when I did not exist, nor you, nor all these kings; nor in the future shall any of us cease to be.'),
  GitaSloka(chapter:2,verse:13,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा |\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति ||',transliteration:'dehino\'sminyathā dehe kaumāraṃ yauvanaṃ jarā | tathā dehāntaraprāptirdhīrastatra na muhyati',teluguMeaning:'ఈ శరీరంలో ఆత్మకు బాల్యం, యౌవనం, వృద్ధాప్యం ఎలా వస్తాయో, అలాగే మరో శరీరం పొందడం కూడా. ధీరుడు దానికి మోహపడడు.',englishMeaning:'As the embodied soul passes in this body from childhood to youth to old age, the soul similarly passes into another body at death. A sober person is not bewildered.'),
  GitaSloka(chapter:2,verse:17,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् |\nविनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति ||',transliteration:'avināśi tu tadviddhi yena sarvamidam tatam | vināśamavyayasyāsya na kaścitkartumarhati',teluguMeaning:'ఈ సమస్తమూ వ్యాపించి ఉన్న దాన్ని అవినాశిగా తెలుసుకో. ఈ అవ్యయమైన దాన్ని నాశనం చేయడానికి ఎవరూ సమర్థులు కారు.',englishMeaning:'That which pervades the entire body is indestructible. No one is able to destroy that imperishable soul.'),
  GitaSloka(chapter:2,verse:19,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् |\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते ||',transliteration:'ya enaṃ vetti hantāraṃ yaścainaṃ manyate hatam | ubhau tau na vijānīto nāyaṃ hanti na hanyate',teluguMeaning:'ఇది చంపుతుందని అనుకునే వాడు, చంపబడుతుందని అనుకునే వాడు — ఇద్దరూ నిజం తెలుసుకోలేరు. ఇది చంపదు, చంపబడదు.',englishMeaning:'He who thinks this soul is a slayer and he who thinks it is slain — both fail to perceive the truth. This neither slays, nor is it slain.'),
  GitaSloka(chapter:2,verse:20,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः |\nअजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे ||',transliteration:'na jāyate mriyate vā kadācin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ | ajo nityaḥ śāśvato\'yaṃ purāṇo na hanyate hanyamāne śarīre',teluguMeaning:'ఈ ఆత్మ పుట్టదు, చావదు. అజుడు, నిత్యుడు, శాశ్వతుడు, పురాతనుడు. శరీరం చంపబడినా ఇది చంపబడదు.',englishMeaning:'The soul is never born nor dies. It is unborn, eternal, ever-existing, and primeval. It is not slain when the body is slain.'),
  GitaSloka(chapter:2,verse:22,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि |\nतथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही ||',transliteration:'vāsāṃsi jīrṇāni yathā vihāya navāni gṛhṇāti naro\'parāṇi | tathā śarīrāṇi vihāya jīrṇānyanyāni saṃyāti navāni dehī',teluguMeaning:'మనిషి పాత వస్త్రాలు వదిలిపెట్టి కొత్తవి ధరించినట్లు, ఆత్మ పాత శరీరాలు వదిలిపెట్టి కొత్త శరీరాలు పొందుతుంది.',englishMeaning:'As a person puts on new garments giving up old ones, the soul accepts new material bodies giving up the old and useless ones.'),
  GitaSloka(chapter:2,verse:23,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः |\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः ||',transliteration:'nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ | na cainaṃ kledayantyāpo na śoṣayati mārutaḥ',teluguMeaning:'ఆయుధాలు దీన్ని ఛేదించలేవు, అగ్ని దహించలేదు, జలం తడపలేదు, వాయువు ఎండించలేదు.',englishMeaning:'The soul can never be cut by any weapon, burned by fire, moistened by water, nor withered by the wind.'),
  GitaSloka(chapter:2,verse:47,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन |\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि ||',transliteration:'karmaṇyevādhikāraste mā phaleṣu kadācana | mā karmaphalaheturbhūrmā te saṅgo\'stvakarmaṇi',teluguMeaning:'కర్మ చేయడంలో మాత్రమే నీకు అధికారం ఉంది, ఫలాలపై ఎప్పుడూ లేదు. కర్మఫలానికి కారణం కాకు, అకర్మలో ఆసక్తి వద్దు.',englishMeaning:'You have a right to perform your prescribed duties, but you are not entitled to the fruits of your actions. Never consider yourself the cause of the results, and never be attached to inaction.'),
  GitaSloka(chapter:2,verse:48,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय |\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते ||',transliteration:'yogasthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanañjaya | siddhyasiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate',teluguMeaning:'ఓ ధనంజయా! ఆసక్తి వదిలిపెట్టి, సిద్ధి అసిద్ధులలో సమత్వం పాటించి యోగస్థితిలో కర్మలు చేయి. సమత్వమే యోగం అంటారు.',englishMeaning:'Be steadfast in yoga, O Arjuna. Perform your duty and abandon all attachment to success or failure. Such evenness of mind is called yoga.'),
  GitaSloka(chapter:2,verse:55,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् |\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते ||',transliteration:'prajahāti yadā kāmān sarvān pārtha manogatān | ātmanyevātmanā tuṣṭaḥ sthitaprajñastadocyate',teluguMeaning:'ఓ పార్థా! మనసులోని సమస్త కోరికలను వదిలిపెట్టి, ఆత్మ యందే సంతుష్టుడైనప్పుడు అతనిని స్థితప్రజ్ఞుడు అంటారు.',englishMeaning:'O Partha, when a man gives up all varieties of desire that arise in the mind, and finds satisfaction in the self alone, then he is said to be in pure transcendental consciousness.'),
  GitaSloka(chapter:2,verse:62,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते |\nसङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ||',transliteration:'dhyāyato viṣayān puṃsaḥ saṅgasteṣūpajāyate | saṅgāt sañjāyate kāmaḥ kāmāt krodho\'bhijāyate',teluguMeaning:'విషయాలను ధ్యానిస్తున్న పురుషుడికి వాటిపై ఆసక్తి పుడుతుంది. ఆసక్తి నుండి కోరిక పుడుతుంది, కోరిక నుండి కోపం పుడుతుంది.',englishMeaning:'While contemplating the objects of the senses, a person develops attachment, from attachment lust develops, and from lust anger arises.'),
  GitaSloka(chapter:2,verse:63,chapterTitle:'Sankhya Yoga',chapterTeluguTitle:'సాంఖ్య యోగము',sanskrit:'क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः |\nस्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ||',transliteration:'krodhādbhavati sammohaḥ sammohāt smṛtivibhramaḥ | smṛtibhraṃśādbuddhināśo buddhināśāt praṇaśyati',teluguMeaning:'కోపం నుండి మోహం, మోహం నుండి స్మృతి భ్రంశం, స్మృతి నశించడంతో బుద్ధి నాశనం, బుద్ధి నాశనంతో మనిషి నాశనమవుతాడు.',englishMeaning:'From anger comes delusion, from delusion bewilderment of memory, when memory is bewildered intelligence is lost, and when intelligence is lost one falls down.'),

  // CHAPTER 3
  GitaSloka(chapter:3,verse:8,chapterTitle:'Karma Yoga',chapterTeluguTitle:'కర్మ యోగము',sanskrit:'नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः |\nशरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः ||',transliteration:'niyataṃ kuru karma tvaṃ karma jyāyo hyakarmaṇaḥ | śarīrayātrāpi ca te na prasiddhyedakarmaṇaḥ',teluguMeaning:'నీకు విధించిన కర్మ చేయి. అకర్మ కంటే కర్మ శ్రేష్ఠం. కర్మ లేకుండా నీ శరీర యాత్ర కూడా సాగదు.',englishMeaning:'Perform your prescribed duty, for action is better than inaction. A man cannot even maintain his physical body without work.'),
  GitaSloka(chapter:3,verse:21,chapterTitle:'Karma Yoga',chapterTeluguTitle:'కర్మ యోగము',sanskrit:'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः |\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते ||',transliteration:'yadyadācarati śreṣṭhas tattadevetaro janaḥ | sa yatpramāṇaṃ kurute lokas tadanuvartate',teluguMeaning:'శ్రేష్ఠుడు ఏమి చేస్తాడో ఇతర జనులు అదే చేస్తారు. అతడు ఏ ప్రమాణం చూపితే లోకం దాన్నే అనుసరిస్తుంది.',englishMeaning:'Whatever action a great man performs, common men follow. And whatever standards he sets by exemplary acts, all the world pursues.'),
  GitaSloka(chapter:3,verse:27,chapterTitle:'Karma Yoga',chapterTeluguTitle:'కర్మ యోగము',sanskrit:'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः |\nअहंकारविमूढात्मा कर्ताहमिति मन्यते ||',transliteration:'prakṛteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśaḥ | ahaṃkāravimūḍhātmā kartāhamiti manyate',teluguMeaning:'సమస్త కర్మలు ప్రకృతి గుణాల చేత చేయబడుతున్నాయి. అహంకారంతో మోహపడిన ఆత్మ తానే కర్తనని భావిస్తుంది.',englishMeaning:'The bewildered spirit soul, under the influence of the three modes of material nature, thinks himself to be the doer of activities that are in actuality carried out by nature.'),
  GitaSloka(chapter:3,verse:35,chapterTitle:'Karma Yoga',chapterTeluguTitle:'కర్మ యోగము',sanskrit:'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् |\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः ||',transliteration:'śreyānsvadharmo viguṇaḥ paradharmāt svanuṣṭhitāt | svadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ',teluguMeaning:'పరధర్మాన్ని చక్కగా ఆచరించడం కంటే లోపాలతో కూడిన స్వధర్మం శ్రేయస్కరం. స్వధర్మంలో మరణం శ్రేయస్కరం, పరధర్మం భయావహం.',englishMeaning:'It is far better to discharge one\'s own prescribed duties, even faultily, than another\'s duties perfectly. Destruction in one\'s own duty is better than engaging in another\'s duties.'),

  // CHAPTER 4
  GitaSloka(chapter:4,verse:7,chapterTitle:'Jnana Karma Sanyasa Yoga',chapterTeluguTitle:'జ్ఞాన కర్మ సన్యాస యోగము',sanskrit:'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत |\nअभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम् ||',transliteration:'yadā yadā hi dharmasya glānir bhavati bhārata | abhyutthānamadharmasya tadātmānaṃ sṛjāmyaham',teluguMeaning:'ఓ భారతా! ఎప్పుడెప్పుడు ధర్మానికి క్షీణత కలుగుతుందో, అధర్మం పెరుగుతుందో, అప్పుడప్పుడు నన్ను నేను సృష్టించుకుంటాను (అవతరిస్తాను).',englishMeaning:'Whenever and wherever there is a decline in religious practice, and a predominant rise of irreligion — at that time I descend Myself.'),
  GitaSloka(chapter:4,verse:8,chapterTitle:'Jnana Karma Sanyasa Yoga',chapterTeluguTitle:'జ్ఞాన కర్మ సన్యాస యోగము',sanskrit:'परित्राणाय साधूनां विनाशाय च दुष्कृताम् |\nधर्मसंस्थापनार्थाय सम्भवामि युगे युगे ||',transliteration:'paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām | dharmasaṃsthāpanārthāya sambhavāmi yuge yuge',teluguMeaning:'సజ్జనులను రక్షించడానికి, దుష్టులను నాశనం చేయడానికి, ధర్మాన్ని నెలకొల్పడానికి యుగం యుగంలో అవతరిస్తాను.',englishMeaning:'To deliver the pious and to annihilate the miscreants, as well as to reestablish the principles of religion, I Myself appear millennium after millennium.'),
  GitaSloka(chapter:4,verse:9,chapterTitle:'Jnana Karma Sanyasa Yoga',chapterTeluguTitle:'జ్ఞాన కర్మ సన్యాస యోగము',sanskrit:'जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः |\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन ||',transliteration:'janma karma ca me divyam evaṃ yo vetti tattvataḥ | tyaktvā dehaṃ punarjanma naiti māmeti so\'rjuna',teluguMeaning:'ఓ అర్జునా! నా జన్మ మరియు కర్మ దివ్యమైనవని తత్త్వంగా తెలిసిన వాడు శరీరం వదిలిన తర్వాత పునర్జన్మ పొందడు, నన్ను పొందుతాడు.',englishMeaning:'One who knows the transcendental nature of My appearance and activities does not take birth again after leaving the body, but attains My eternal abode, O Arjuna.'),
  GitaSloka(chapter:4,verse:38,chapterTitle:'Jnana Karma Sanyasa Yoga',chapterTeluguTitle:'జ్ఞాన కర్మ సన్యాస యోగము',sanskrit:'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते |\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति ||',transliteration:'na hi jñānena sadṛśaṃ pavitram iha vidyate | tat svayaṃ yogasaṃsiddhaḥ kālenātmani vindati',teluguMeaning:'ఇక్కడ జ్ఞానంతో సమానమైన పవిత్రమైనది ఏమీ లేదు. యోగంలో సిద్ధుడైన వాడు కాలక్రమంలో దానిని తన ఆత్మలోనే పొందుతాడు.',englishMeaning:'In this world, there is nothing so sublime and pure as transcendental knowledge. Such knowledge is the mature fruit of all mysticism.'),

  // CHAPTER 5
  GitaSloka(chapter:5,verse:18,chapterTitle:'Karma Sanyasa Yoga',chapterTeluguTitle:'కర్మ సన్యాస యోగము',sanskrit:'विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि |\nशुनि चैव श्वपाके च पण्डिताः समदर्शिनः ||',transliteration:'vidyāvinayasampanne brāhmaṇe gavi hastini | śuni caiva śvapāke ca paṇḍitāḥ samadarśinaḥ',teluguMeaning:'పండితులు విద్య వినయాలతో కూడిన బ్రాహ్మణుడిలో, ఆవులో, ఏనుగులో, కుక్కలో మరియు చండాలుడిలో సమదర్శులవుతారు.',englishMeaning:'The humble sages, by virtue of true knowledge, see with equal vision a learned Brahmana, a cow, an elephant, a dog, and a dog-eater.'),
  GitaSloka(chapter:5,verse:29,chapterTitle:'Karma Sanyasa Yoga',chapterTeluguTitle:'కర్మ సన్యాస యోగము',sanskrit:'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् |\nसुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति ||',transliteration:'bhoktāraṃ yajñatapasāṃ sarvalokamaheśvaram | suhṛdaṃ sarvabhūtānāṃ jñātvā māṃ śāntimṛcchati',teluguMeaning:'యజ్ఞతపస్సుల ఫలాన్ని అనుభవించే వాడిగా, సమస్త లోకాలకు మహేశ్వరుడిగా, సమస్త జీవులకు మిత్రుడిగా నన్ను తెలుసుకున్న వాడు శాంతి పొందుతాడు.',englishMeaning:'A person in full consciousness of Me, knowing Me to be the ultimate beneficiary of all sacrifices and austerities, the Supreme Lord of all planets, and the benefactor of all living entities, attains peace.'),

  // CHAPTER 6
  GitaSloka(chapter:6,verse:5,chapterTitle:'Dhyana Yoga',chapterTeluguTitle:'ధ్యాన యోగము',sanskrit:'उद्धरेदात्मनात्मानं नात्मानमवसादयेत् |\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः ||',transliteration:'uddharedātmanātmānaṃ nātmānamavasādayet | ātmaiva hyātmano bandhurātmaiva ripurātmanaḥ',teluguMeaning:'ఆత్మ చేత ఆత్మను ఉద్ధరించుకో, ఆత్మను అధోగతి పాలుచేసుకోకు. ఆత్మయే ఆత్మకు మిత్రుడు, ఆత్మయే ఆత్మకు శత్రువు.',englishMeaning:'One must deliver himself with the help of his mind, and not degrade himself. The mind is the friend of the conditioned soul, and his enemy as well.'),
  GitaSloka(chapter:6,verse:35,chapterTitle:'Dhyana Yoga',chapterTeluguTitle:'ధ్యాన యోగము',sanskrit:'असंशयं महाबाहो मनो दुर्निग्रहं चलम् |\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ||',transliteration:'asaṃśayaṃ mahābāho mano durnigrahaṃ calam | abhyāsena tu kaunteya vairāgyeṇa ca gṛhyate',teluguMeaning:'నిస్సందేహంగా మనసు చంచలమైనది, నిగ్రహించడం కష్టం. కానీ ఓ కుంతీపుత్రా! అభ్యాసం మరియు వైరాగ్యంతో దాన్ని నిగ్రహించవచ్చు.',englishMeaning:'O mighty-armed, it is undoubtedly very difficult to curb the restless mind, but it is possible by suitable practice and by detachment.'),

  // CHAPTER 7
  GitaSloka(chapter:7,verse:7,chapterTitle:'Vijnana Yoga',chapterTeluguTitle:'విజ్ఞాన యోగము',sanskrit:'मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय |\nमयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव ||',transliteration:'mattaḥ parataraṃ nānyat kiñcidasti dhanañjaya | mayi sarvamidaṃ protaṃ sūtre maṇigaṇā iva',teluguMeaning:'ఓ ధనంజయా! నా కంటే ఉన్నతమైనది ఏదీ లేదు. సూత్రంలో మణులు ఉన్నట్లు ఇదంతా నా యందు ఉంది.',englishMeaning:'O conqueror of wealth, there is no truth superior to Me. Everything rests upon Me, as pearls are strung on a thread.'),
  GitaSloka(chapter:7,verse:19,chapterTitle:'Vijnana Yoga',chapterTeluguTitle:'విజ్ఞాన యోగము',sanskrit:'बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते |\nवासुदेवः सर्वमिति स महात्मा सुदुर्लभः ||',transliteration:'bahūnāṃ janmanāmante jñānavānmāṃ prapadyate | vāsudevaḥ sarvamiti sa mahātmā sudurlabhaḥ',teluguMeaning:'అనేక జన్మల తర్వాత జ్ఞానవంతుడు "వాసుదేవుడే సర్వమూ" అని నన్ను శరణు పొందుతాడు. అటువంటి మహాత్ముడు చాలా అరుదు.',englishMeaning:'After many births and deaths, he who is actually in knowledge surrenders unto Me, knowing Me to be the cause of all causes. Such a great soul is very rare.'),

  // CHAPTER 8
  GitaSloka(chapter:8,verse:7,chapterTitle:'Akshara Brahma Yoga',chapterTeluguTitle:'అక్షర బ్రహ్మ యోగము',sanskrit:'तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च |\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयम् ||',transliteration:'tasmāt sarveṣu kāleṣu māmanusmara yudhya ca | mayyarpitamanobuddhirmāmevaiṣyasyasaṃśayam',teluguMeaning:'కాబట్టి సర్వ కాలాలలో నన్ను స్మరించు, యుద్ధం చేయి. మనో బుద్ధులు నాకు అర్పించిన వాడు నిస్సందేహంగా నన్నే పొందుతాడు.',englishMeaning:'Therefore, Arjuna, you should always think of Me and at the same time carry out your prescribed duty. With your mind and intelligence fixed on Me, you will attain Me without doubt.'),
  GitaSloka(chapter:8,verse:16,chapterTitle:'Akshara Brahma Yoga',chapterTeluguTitle:'అక్షర బ్రహ్మ యోగము',sanskrit:'आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन |\nमामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते ||',transliteration:'ābrahma bhuvanāllokāḥ punarāvartino\'rjuna | māmupetya tu kaunteya punarjanma na vidyate',teluguMeaning:'ఓ అర్జునా! బ్రహ్మలోకం వరకు అన్ని లోకాలకు పునర్జన్మ ఉంది. ఓ కుంతీపుత్రా! నన్ను పొందిన వానికి పునర్జన్మ లేదు.',englishMeaning:'From the highest planet down to the lowest, all are places of misery wherein repeated birth and death take place. But one who attains My abode never takes birth again.'),

  // CHAPTER 9
  GitaSloka(chapter:9,verse:22,chapterTitle:'Raja Vidya Raja Guhya Yoga',chapterTeluguTitle:'రాజ విద్యా రాజ గుహ్య యోగము',sanskrit:'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते |\nतेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम् ||',transliteration:'ananyāścintayanto māṃ ye janāḥ paryupāsate | teṣāṃ nityābhiyuktānāṃ yogakṣemaṃ vahāmyaham',teluguMeaning:'అనన్య భావంతో నన్నే ధ్యానిస్తూ ఆరాధించే వారికి, నిత్యం నా యందు ఉండే వారికి యోగ క్షేమాలను నేనే వహిస్తాను.',englishMeaning:'But those who always worship Me with exclusive devotion, meditating on My transcendental form — to them I carry what they lack, and I preserve what they have.'),
  GitaSloka(chapter:9,verse:26,chapterTitle:'Raja Vidya Raja Guhya Yoga',chapterTeluguTitle:'రాజ విద్యా రాజ గుహ్య యోగము',sanskrit:'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति |\nतदहं भक्त्युपहृतमश्नामि प्रयतात्मनः ||',transliteration:'patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati | tadahaṃ bhaktyupahṛtamaśnāmi prayatātmanaḥ',teluguMeaning:'పత్రమైనా, పువ్వైనా, పండైనా, జలమైనా భక్తితో నాకు ఇచ్చే వాడి భక్తి ప్రేమతో ఇచ్చినదాన్ని నేను స్వీకరిస్తాను.',englishMeaning:'If one offers Me with love and devotion a leaf, a flower, fruit or water, I will accept it.'),
  GitaSloka(chapter:9,verse:34,chapterTitle:'Raja Vidya Raja Guhya Yoga',chapterTeluguTitle:'రాజ విద్యా రాజ గుహ్య యోగము',sanskrit:'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु |\nमामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः ||',transliteration:'manmanā bhava madbhakto madyājī māṃ namaskuru | māmevaiṣyasi yuktvaivaṃ ātmānaṃ matparāyaṇaḥ',teluguMeaning:'నా యందు మనసు నిలుపు, నా భక్తుడవు కమ్ము, నాకు యజ్ఞం చేయి, నమస్కరించు. ఇలా నన్నే పరమగతిగా పొందావు.',englishMeaning:'Engage your mind always in thinking of Me, become My devotee, offer obeisances to Me and worship Me. Being completely absorbed in Me, surely you will come to Me.'),

  // CHAPTER 10
  GitaSloka(chapter:10,verse:20,chapterTitle:'Vibhuti Yoga',chapterTeluguTitle:'విభూతి యోగము',sanskrit:'अहमात्मा गुडाकेश सर्वभूताशयस्थितः |\nअहमादिश्च मध्यं च भूतानामन्त एव च ||',transliteration:'ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ | ahamādiśca madhyaṃ ca bhūtānāmanta eva ca',teluguMeaning:'ఓ గుడాకేశా! నేను సమస్త జీవుల హృదయంలో ఉండే ఆత్మను. జీవులకు ఆదియు, మధ్యమును, అంతమును నేనే.',englishMeaning:'I am the Self, O Gudakesha, seated in the hearts of all creatures. I am the beginning, the middle and the end of all beings.'),
  GitaSloka(chapter:10,verse:41,chapterTitle:'Vibhuti Yoga',chapterTeluguTitle:'విభూతి యోగము',sanskrit:'यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा |\nतत्तदेवावगच्छ त्वं मम तेजोंशसम्भवम् ||',transliteration:'yadyadvibhūtimat sattvaṃ śrīmadūrjitameva vā | tattadevāvagaccha tvaṃ mama tejo\'ṃśasambhavam',teluguMeaning:'వైభవంగల, శ్రీమంతమైన, శక్తివంతమైన ఏ వస్తువు అయినా నా తేజస్సు యొక్క అంశ నుండి పుట్టినదే అని తెలుసుకో.',englishMeaning:'Know that all opulent, beautiful, and glorious creations spring from but a spark of My splendor.'),

  // CHAPTER 11
  GitaSloka(chapter:11,verse:8,chapterTitle:'Vishwarupa Darshana Yoga',chapterTeluguTitle:'విశ్వరూప దర్శన యోగము',sanskrit:'न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा |\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् ||',transliteration:'na tu māṃ śakyase draṣṭumanenaiva svacakṣuṣā | divyaṃ dadāmi te cakṣuḥ paśya me yogamaiśvaram',teluguMeaning:'కానీ ఈ నీ కళ్ళతో నన్ను చూడలేవు. నీకు దివ్యదృష్టి ఇస్తున్నాను. నా ఐశ్వర్య యోగాన్ని చూడుము.',englishMeaning:'But you cannot see Me with your present eyes. Therefore I give you divine eyes. Behold My mystic opulence!'),
  GitaSloka(chapter:11,verse:32,chapterTitle:'Vishwarupa Darshana Yoga',chapterTeluguTitle:'విశ్వరూప దర్శన యోగము',sanskrit:'कालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः |\nऋतेऽपि त्वां न भविष्यन्ति सर्वे येऽवस्थिताः प्रत्यनीकेषु योधाः ||',transliteration:'kālo\'smi lokakṣayakṛtpravṛddho lokānsamāhartumiha pravṛttaḥ | ṛte\'pi tvāṃ na bhaviṣyanti sarve ye\'vasthitāḥ pratyanīkeṣu yodhāḥ',teluguMeaning:'నేను లోకాలను నాశనం చేసే కాలాన్ని. నువ్వు లేకపోయినా శత్రు సైన్యంలో ఉన్న వారందరూ ఉండరు.',englishMeaning:'Time I am, the great destroyer of the worlds. With the exception of you (the Pandavas), all the soldiers here on both sides will be slain.'),

  // CHAPTER 12
  GitaSloka(chapter:12,verse:8,chapterTitle:'Bhakti Yoga',chapterTeluguTitle:'భక్తి యోగము',sanskrit:'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय |\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ||',transliteration:'mayyeva mana ādhatsva mayi buddhiṃ niveśaya | nivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ',teluguMeaning:'నా యందే మనసు నిలుపు, నా యందే బుద్ధి నిలుపు. ఇకముందు నా యందే నివసిస్తావు — ఇందులో సందేహం లేదు.',englishMeaning:'Just fix your mind upon Me and engage all your intelligence in Me. Thus you will live in Me always, without a doubt.'),
  GitaSloka(chapter:12,verse:13,chapterTitle:'Bhakti Yoga',chapterTeluguTitle:'భక్తి యోగము',sanskrit:'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च |\nनिर्ममो निरहंकारः समदुःखसुखः क्षमी ||',transliteration:'adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca | nirmamo nirahaṃkāraḥ samaduḥkhasukhaḥ kṣamī',teluguMeaning:'సమస్త జీవులపై ద్వేషం లేనివాడు, మైత్రీ కరుణలు కలవాడు, మమకారం అహంకారం లేనివాడు, సుఖ దుఃఖాలలో సమంగా ఉండే వాడు, క్షమాశీలుడు.',englishMeaning:'One who is not envious but is a kind friend to all living entities, who is free from false ego, who is equal in both happiness and distress, who is tolerant.'),

  // CHAPTER 13
  GitaSloka(chapter:13,verse:2,chapterTitle:'Kshetra Kshetrajna Vibhaga Yoga',chapterTeluguTitle:'క్షేత్ర క్షేత్రజ్ఞ విభాగ యోగము',sanskrit:'क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत |\nक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम ||',transliteration:'kṣetrajñaṃ cāpi māṃ viddhi sarvakṣetreṣu bhārata | kṣetrakṣetrajñayor jñānaṃ yattajjñānaṃ mataṃ mama',teluguMeaning:'ఓ భారతా! సమస్త క్షేత్రాలలో క్షేత్రజ్ఞుడిగా నన్ను తెలుసుకో. క్షేత్ర క్షేత్రజ్ఞుల జ్ఞానమే నా దృష్టిలో జ్ఞానం.',englishMeaning:'You should understand that I am also the knower in all bodies. To understand this body and its knower is called knowledge. That is My opinion.'),

  // CHAPTER 14
  GitaSloka(chapter:14,verse:5,chapterTitle:'Gunatraya Vibhaga Yoga',chapterTeluguTitle:'గుణత్రయ విభాగ యోగము',sanskrit:'सत्त्वं रजस्तम इति गुणाः प्रकृतिसम्भवाः |\nनिबध्नन्ति महाबाहो देहे देहिनमव्ययम् ||',transliteration:'sattvaṃ rajastama iti guṇāḥ prakṛtisambhavāḥ | nibadhnanti mahābāho dehe dehinamavyayam',teluguMeaning:'ఓ మహాబాహూ! సత్త్వ రజ తమో గుణాలు ప్రకృతి నుండి పుట్టాయి. అవ్యయుడైన ఆత్మను శరీరంలో బంధిస్తాయి.',englishMeaning:'Material nature consists of three modes — goodness, passion and ignorance. When the eternal living entity comes in contact with nature, he becomes conditioned by these modes.'),

  // CHAPTER 15
  GitaSloka(chapter:15,verse:15,chapterTitle:'Purushottama Yoga',chapterTeluguTitle:'పురుషోత్తమ యోగము',sanskrit:'सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च |\nवेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम् ||',transliteration:'sarvasya cāhaṃ hṛdi sanniviṣṭo mattaḥ smṛtirjñānamapohanaṃ ca | vedaiśca sarvairahameva vedyo vedāntakṛdvedavideva cāham',teluguMeaning:'నేను అందరి హృదయంలో నిలిచి ఉన్నాను. నా నుండే స్మృతి, జ్ఞానం కలుగుతాయి. వేదాంత కర్తను, వేదవిదుడను నేనే.',englishMeaning:'I am seated in everyone\'s heart, and from Me come remembrance, knowledge and forgetfulness. By all the Vedas, I am to be known. Indeed, I am the compiler of Vedanta.'),

  // CHAPTER 16
  GitaSloka(chapter:16,verse:21,chapterTitle:'Daivasura Sampad Vibhaga Yoga',chapterTeluguTitle:'దైవాసుర సంపద్ విభాగ యోగము',sanskrit:'त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः |\nकामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत् ||',transliteration:'trividhaṃ narakasyedaṃ dvāraṃ nāśanamātmanaḥ | kāmaḥ krodhas tathā lobhas tasmādetattrayaṃ tyajet',teluguMeaning:'కామం, కోపం మరియు లోభం — ఇవి ఆత్మను నాశనం చేసే నరకానికి మూడు ద్వారాలు. కాబట్టి ఈ మూడింటినీ వదిలిపెట్టాలి.',englishMeaning:'There are three gates leading to this hell — lust, anger, and greed. Every sane man should give these up, for they lead to the degradation of the soul.'),

  // CHAPTER 17
  GitaSloka(chapter:17,verse:3,chapterTitle:'Shraddhatraya Vibhaga Yoga',chapterTeluguTitle:'శ్రద్ధాత్రయ విభాగ యోగము',sanskrit:'सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत |\nश्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः ||',transliteration:'sattvānurūpā sarvasya śraddhā bhavati bhārata | śraddhāmayo\'yaṃ puruṣo yo yacchraddhaḥ sa eva saḥ',teluguMeaning:'ఓ భారతా! ప్రతి ఒక్కరి శ్రద్ధ వారి స్వభావ గుణాలకు అనుగుణంగా ఉంటుంది. మనిషి శ్రద్ధతో నిర్మితుడు — ఏ శ్రద్ధ కలవాడైతే అతడే అది.',englishMeaning:'O son of Bharata, according to one\'s existence under the various modes of nature, one evolves a particular kind of faith. The living being is said to be of a particular faith according to the modes he has acquired.'),

  // CHAPTER 18
  GitaSloka(chapter:18,verse:46,chapterTitle:'Moksha Sanyasa Yoga',chapterTeluguTitle:'మోక్ష సన్యాస యోగము',sanskrit:'यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम् |\nस्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ||',transliteration:'yataḥ pravṛttir bhūtānāṃ yena sarvamidaṃ tatam | svakarmaNā tamabhyarcya siddhiṃ vindati mānavaḥ',teluguMeaning:'ఎవరి నుండి జీవులకు ప్రవృత్తి కలుగుతుందో, ఎవరు ఈ సర్వమూ వ్యాపించి ఉన్నారో — ఆయనను స్వకర్మతో పూజించి మానవుడు సిద్ధి పొందుతాడు.',englishMeaning:'By worship of the Lord, who is the source of all beings and who is all-pervading, a man can attain perfection through performing his own work.'),
  GitaSloka(chapter:18,verse:65,chapterTitle:'Moksha Sanyasa Yoga',chapterTeluguTitle:'మోక్ష సన్యాస యోగము',sanskrit:'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु |\nमामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ||',transliteration:'manmanā bhava madbhakto madyājī māṃ namaskuru | māmevaiṣyasi satyaṃ te pratijāne priyo\'si me',teluguMeaning:'నా యందే మనసు నిలుపు, నా భక్తుడవు కమ్ము, నాకు పూజ చేయి, నమస్కరించు. నన్నే పొందుతావు — నీకు నిజంగా వాగ్దానం చేస్తున్నాను, నువ్వు నాకు ప్రియుడివి.',englishMeaning:'Always think of Me, become My devotee, worship Me, and offer your homage unto Me. Thus you will come to Me without fail. I promise you this because you are My very dear friend.'),
  GitaSloka(chapter:18,verse:66,chapterTitle:'Moksha Sanyasa Yoga',chapterTeluguTitle:'మోక్ష సన్యాస యోగము',sanskrit:'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज |\nअहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः ||',transliteration:'sarvadharmānparityajya māmekaṃ śaraṇaṃ vraja | ahaṃ tvāṃ sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ',teluguMeaning:'సమస్త ధర్మాలను వదిలిపెట్టి నన్ను మాత్రమే శరణు పొందుము. సమస్త పాపాల నుండి నిన్ను విముక్తి చేస్తాను. శోకించకు.',englishMeaning:'Abandon all varieties of religion and just surrender unto Me. I shall deliver you from all sinful reactions. Do not fear.'),
  GitaSloka(chapter:18,verse:78,chapterTitle:'Moksha Sanyasa Yoga',chapterTeluguTitle:'మోక్ష సన్యాస యోగము',sanskrit:'यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः |\nतत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम ||',transliteration:'yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanurdharaḥ | tatra śrīrvijayo bhūtirdhṛuvā nītirmatirmama',teluguMeaning:'యోగేశ్వరుడైన కృష్ణుడు ఉన్న చోట, ధనుర్ధారియైన పార్థుడు ఉన్న చోట — అక్కడ శ్రీ, విజయం, వైభవం, స్థిర నీతి ఉంటాయని నా అభిప్రాయం.',englishMeaning:'Wherever there is Krishna, the master of all mystics, and wherever there is Arjuna, the supreme archer, there will also certainly be opulence, victory, extraordinary power, and morality. That is my opinion.'),
];
